#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    // dp[v] = longest +1-step subsequence of the prefix that ends with value v.
    unordered_map<long long, int> dp;
    dp.reserve(2 * n + 1);
    int answer = 0;
    for (int i = 0; i < n; i++) {
        long long v;
        scanf("%lld", &v);
        auto it = dp.find(v - 1);
        int cand = (it == dp.end() ? 0 : it->second) + 1;
        int &cur = dp[v];
        cur = max(cur, cand);
        answer = max(answer, cur);
    }
    printf("%d\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        // dp[v] = longest +1-step subsequence of the prefix that ends with value v.
        HashMap<Long, Integer> dp = new HashMap<>(2 * n + 1);
        int answer = 0;
        for (int i = 0; i < n; i++) {
            st.nextToken();
            long v = (long) st.nval;
            int cand = dp.getOrDefault(v - 1, 0) + 1;
            int cur = Math.max(dp.getOrDefault(v, 0), cand);
            dp.put(v, cur);
            answer = Math.max(answer, cur);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	// dp[v] = longest +1-step subsequence of the prefix that ends with value v.
	dp := make(map[int]int, n)
	answer := 0
	for i := 0; i < n; i++ {
		v := nextInt()
		dp[v] = max(dp[v], dp[v-1]+1)
		answer = max(answer, dp[v])
	}
	fmt.Println(answer)
}
